/*!
 * Chart.js local fallback.
 * NOTE: Application pages load Chart.js from CDN:
 *   https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js
 * This local file provides a minimal scriptable charting shim (bar, line,
 * pie via canvas + 2D API) so dashboards do not fatal when the CDN is down.
 */
(function (global) {
  function Chart(ctx, config) {
    if (typeof ctx === 'string') ctx = document.getElementById(ctx);
    if (!ctx) return;
    var canvas = ctx;
    var type = (config && config.type) || 'bar';
    var data = (config && config.data) || { labels: [], datasets: [] };
    var ds = (data.datasets && data.datasets[0]) || {};
    this.ctx = canvas.getContext('2d');
    this.data = data;
    this.type = type;
    this.options = (config && config.options) || {};
    this.update = function () { draw(this); return this; };
    this.destroy = function () { var c = this.ctx; c.clearRect(0, 0, canvas.width, canvas.height); };
    this.update();
  }
  function pickColor(i) {
    var palette = ['#6366f1', '#06b6d4', '#10b981', '#f59e0b', '#ef4444', '#3b82f6', '#8b5cf6', '#ec4899'];
    return palette[i % palette.length];
  }
  function draw(chart) {
    var ctx = chart.ctx, data = chart.data;
    var labels = data.labels || [];
    var ds = (data.datasets && data.datasets[0]) || { data: [] };
    var values = ds.data || [];
    var W = ctx.canvas.width, H = ctx.canvas.height;
    ctx.clearRect(0, 0, W, H);
    if (!labels.length) return;
    var pad = 30, bottom = H - pad, max = Math.max.apply(null, values.filter(function (v) { return v != null; }).concat([1]));
    var bw = (W - pad * 2) / labels.length;
    if (chart.type === 'pie' || chart.type === 'doughnut') {
      var total = values.reduce(function (s, v) { return s + (v || 0); }, 0) || 1;
      var start = -Math.PI / 2;
      var cx = W / 2, cy = H / 2, r = Math.min(W, H) / 2 - pad;
      values.forEach(function (v, i) {
        var angle = (v / total) * Math.PI * 2;
        ctx.beginPath();
        ctx.moveTo(cx, cy);
        ctx.arc(cx, cy, r, start, start + angle);
        ctx.closePath();
        ctx.fillStyle = pickColor(i);
        ctx.fill();
        start += angle;
      });
      return;
    }
    labels.forEach(function (label, i) {
      var v = values[i] || 0;
      var h = (v / max) * (H - pad * 2);
      ctx.fillStyle = pickColor(i);
      ctx.fillRect(pad + i * bw + bw * 0.15, H - pad - h, bw * 0.7, h);
      ctx.fillStyle = '#94a3b8';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(String(label), pad + i * bw + bw / 2, H - 8);
    });
    ctx.strokeStyle = '#2d2d50';
    ctx.beginPath(); ctx.moveTo(pad, 0); ctx.lineTo(pad, H - pad); ctx.stroke();
  }
  global.Chart = Chart;
})(window);
